            *self.edit = Some(edit);
            semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "decoded edit structural retirement found a live mutation owner")
        })?;
        *self.active = Some(Box::new(retirement));
