fn artifact_link_spec_controlled<C: crate::os_dsl::NativeSchemaControl>(control: &mut C) -> Result<crate::os_dsl::RecordSpec, semio_framework_value::ValueError> {
    control.scoped_stage(|control| {
        control.begin_stage(3)?;
        let mut fields = control.allocate_vec(3)?;
        let target = <crate::os_io::ArtifactRef as crate::os_dsl::DslField>::shape_controlled(control)?;
        for (id, key, shape) in [(0, "target", target), (1, "pin", crate::os_dsl::Shape::Record(link_pin_spec_producer())), (2, "role", crate::os_dsl::Shape::Text)] {
            fields.push(crate::os_dsl::schema::producer::field(id, key, shape, control)?);
            control.step()?;
        }
        crate::os_dsl::schema::producer::record(None, crate::os_dsl::RecordLayout::Inline, fields, control)
