fn link_pin_spec_controlled<C: crate::os_dsl::NativeSchemaControl>(control: &mut C) -> Result<crate::os_dsl::RecordSpec, semio_framework_value::ValueError> {
    control.scoped_stage(|control| {
        control.begin_stage(5)?;
        let mut fields = control.allocate_vec(5)?;
        let mut labels = control.allocate_vec(3)?;
        for (key, id) in [("head", 0), ("checkpoint", 1), ("snapshot", 2)] {
            labels.push((control.copy_text(key)?, id));
        }
        fields.push(crate::os_dsl::schema::producer::field(0, "kind", crate::os_dsl::Shape::Enum(labels), control)?);
        control.step()?;
        for (id, key, shape) in [(1, "checkpoint_id", crate::os_dsl::Shape::Text), (2, "blob_hash", crate::os_dsl::Shape::Text), (3, "blob_size", crate::os_dsl::Shape::UInt), (4, "blob_media_type", crate::os_dsl::Shape::Text)] {
            fields.push(crate::os_dsl::schema::producer::field(id, key, shape, control)?.optional());
            control.step()?;
