pub use presence_peer_rejection::PresencePeerAdmissionRejected;

impl<P: Send + Sync + 'static> PresencePeersPublication<P> {
    fn new(current: &Arc<PresencePeersRoot<P>>, factory: Arc<dyn SnapshotRetirementFactory<P>>) -> Self {
        Self {
            base_root: std::mem::ManuallyDrop::new(Some(current.clone())),
            candidate: std::mem::ManuallyDrop::new(Some(current.clone_aliases())),
            created: std::mem::ManuallyDrop::new(PresencePeersRetiredEntries::empty()),
            retired: std::mem::ManuallyDrop::new(PresencePeersRetiredEntries::empty()),
            active: std::mem::ManuallyDrop::new(None),
            factory,
            prune_cursor: 0,
            pruning_complete: false,
        }
    }

    pub fn prune_one(&mut self, mut keep: impl FnMut(&str) -> bool) -> Result<bool, String> {
        if self.pruning_complete {
            return Ok(false);
        }
        let candidate = self.candidate.as_ref().ok_or_else(|| "presence peer publication candidate is not owned".to_string())?;
        if self.prune_cursor >= candidate.len {
            self.pruning_complete = true;
            return Ok(false);
        }
        let keep_entry = candidate.entries[self.prune_cursor].as_ref().is_some_and(|entry| keep(&entry.actor));
        if keep_entry {
            self.prune_cursor += 1;
            return Ok(true);
        }
        let (next, retired) = candidate.remove_at(self.prune_cursor);
        let previous = self.candidate.replace(next).expect("presence peer publication candidate");
        drop(previous);
        let mut retired = PresencePeersRetiredEntries::one(retired);
        self.retired.append(&mut retired).map_err(|_| "presence peer publication displaced-entry authority is saturated".to_string())?;
        Ok(true)
    }

    pub fn adopt(&mut self, actor: String, presence: P, received_at_ms: i64) -> Result<(), PresencePeerAdmissionRejected<P>> {
        if !self.pruning_complete {
            return Err(PresencePeerAdmissionRejected::new("presence peer publication must finish stale-entry pruning before decode adoption", actor, presence, self.factory.clone()));
        }
        let Some(candidate) = self.candidate.as_ref() else {
            return Err(PresencePeerAdmissionRejected::new("presence peer publication candidate is not owned", actor, presence, self.factory.clone()));
        };
        if actor.is_empty() || actor.len() > PRESENCE_PEER_ID_BYTES {
            return Err(PresencePeerAdmissionRejected::new("presence peer actor is empty or exceeds its fixed byte authority", actor, presence, self.factory.clone()));
        }
        if candidate.len == PRESENCE_PEER_SLOTS && !candidate.entries[..candidate.len].iter().any(|entry| entry.as_ref().is_some_and(|entry| entry.actor.as_str() == actor.as_str())) {
            return Err(PresencePeerAdmissionRejected::new("presence peer root exceeds its fixed item authority", actor, presence, self.factory.clone()));
        }
        let mut next = candidate.clone_aliases();
        let mut index = 0usize;
        while index < next.len && next.entries[index].as_ref().is_some_and(|entry| entry.actor.as_str() < actor.as_str()) {
            index += 1;
        }
        let replaces = next.entries.get(index).and_then(Option::as_ref).is_some_and(|entry| entry.actor.as_str() == actor.as_str());
        if self.created.len == PRESENCE_PEER_SLOTS || (replaces && self.retired.len == PRESENCE_PEER_SLOTS) {
            return Err(PresencePeerAdmissionRejected::new("presence peer publication ownership authority is saturated", actor, presence, self.factory.clone()));
        }
        let presence = Arc::new(presence);
        let inserted = Arc::new(PresencePeerEntry::new(actor, presence, received_at_ms));
        let retired = if replaces {
            next.entries[index].replace(inserted.clone())
        } else {
            for cursor in (index..next.len).rev() {
                next.entries[cursor + 1] = next.entries[cursor].take();
            }
            next.entries[index] = Some(inserted.clone());
            next.len += 1;
            None
        };
        let previous = self.candidate.replace(next).expect("presence peer publication candidate");
        drop(previous);
        let created_index = self.created.len;
        self.created.entries[created_index] = Some(inserted);
        self.created.len += 1;
        if let Some(retired) = retired {
            let retired_index = self.retired.len;
            self.retired.entries[retired_index] = Some(retired);
            self.retired.len += 1;
        }
        Ok(())
    }

    pub fn release_created_one(&mut self) -> bool {
        if self.created.len == 0 {
            return false;
        }
        self.created.len -= 1;
        let index = self.created.len;
        drop(self.created.entries[index].take());
        true
    }

    pub fn take_commit(&mut self) -> Result<PresencePeersCommit<P>, String> {
        if !self.pruning_complete || self.created.len != 0 || self.active.is_some() {
            return Err("presence peer publication is not terminal-ready for commit".into());
        }
        let candidate = Arc::new(self.candidate.take().ok_or_else(|| "presence peer publication candidate was already transferred".to_string())?);
        let retired = std::mem::replace(&mut *self.retired, PresencePeersRetiredEntries::empty());
        let retirement = (!retired.is_empty()).then(|| PresencePeersRetirement::new(retired, self.factory.clone()));
        Ok(PresencePeersCommit { base_root: self.base_root.take().expect("peer candidate retains its exact immutable base"), root: candidate, retirement, factory: self.factory.clone() })
    }

    pub fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError> {
        if maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if let Some(active) = self.active.as_mut() {
            let step = active.close_step(maximum_items, maximum_bytes)?;
            if step != SnapshotRetirementStep::Complete {
                return Ok(step);
            }
            if !active.terminal_is_empty() {
                return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "presence peer publication cleanup reported Complete without its terminal-empty witness"));
            }
            drop(self.active.take());
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if let Some(candidate) = self.candidate.as_mut() {
            if candidate.len != 0 {
                candidate.len -= 1;
                *self.active = Some(PresencePeersRetirement::new(PresencePeersRetiredEntries::one(candidate.entries[candidate.len].take()), self.factory.clone()));
                return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
            }
            drop(self.candidate.take());
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if self.retired.len != 0 {
            self.retired.len -= 1;
            let index = self.retired.len;
            *self.active = Some(PresencePeersRetirement::new(PresencePeersRetiredEntries::one(self.retired.entries[index].take()), self.factory.clone()));
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if self.created.len != 0 {
            let created = std::mem::replace(&mut *self.created, PresencePeersRetiredEntries::empty());
            *self.active = Some(PresencePeersRetirement::new(created, self.factory.clone()));
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if self.base_root.take().is_some() {
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        Ok(SnapshotRetirementStep::Complete)
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.base_root.is_none() && self.candidate.is_none() && self.created.len == 0 && self.retired.len == 0 && self.active.is_none()
    }
}

impl<P> Drop for PresencePeersPublication<P> {
    fn drop(&mut self) {
        if !std::thread::panicking() {
            assert!(
                std::thread::panicking() || (self.base_root.is_none() && self.candidate.is_none() && self.created.len == 0 && self.retired.len == 0 && self.active.is_none()),
                "incomplete presence peer publication reached Drop without bounded disposal"
            );
        }
    }
}

impl<P: Send + Sync + 'static> PresencePeersRetirement<P> {
    fn new(retired: PresencePeersRetiredEntries<P>, factory: Arc<dyn SnapshotRetirementFactory<P>>) -> Self {
        Self {
            root: std::mem::ManuallyDrop::new(None),
            owned_root: std::mem::ManuallyDrop::new(None),
            retired: std::mem::ManuallyDrop::new(retired),
            waiting: std::mem::ManuallyDrop::new(None),
            entry: std::mem::ManuallyDrop::new(None),
            active: std::mem::ManuallyDrop::new(None),
            factory,
            cursor: 0,
        }
    }

    pub fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError> {
        if maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if let Some(active) = self.active.as_mut() {
            return match active.close_step(maximum_items, maximum_bytes)? {
                step @ SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= maximum_items && released_bytes <= maximum_bytes => Ok(step),
                SnapshotRetirementStep::Pending { .. } => Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "presence peer snapshot disposer exceeded its exact item or byte grant")),
                SnapshotRetirementStep::Blocked => Ok(SnapshotRetirementStep::Blocked),
                SnapshotRetirementStep::Complete => {
                    if !active.terminal_is_empty() {
                        return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "presence peer snapshot disposer reported Complete without its terminal-empty witness"));
                    }
                    drop(self.active.take());
                    Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 })
                }
            };
        }
        if let Some(entry) = self.entry.as_mut() {
            if let Some(scalar) = entry.actor.chars().next_back() {
                let bytes = scalar.len_utf8();
                if bytes > maximum_bytes {
                    return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                }
                entry.actor.pop();
                return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: bytes });
            }
            let snapshot = entry.presence.take().ok_or_else(|| semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "presence peer retirement entry lost its exact snapshot authority"))?;
            *self.active = Some(self.factory.retire(snapshot));
            let entry = self.entry.take().expect("empty presence peer retirement entry");
            drop(entry);
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if let Some(waiting) = self.waiting.take() {
            *self.entry = Arc::into_inner(waiting);
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if self.cursor < self.retired.len {
            let index = self.cursor;
            self.cursor += 1;
            if let Some(entry) = self.retired.entries[index].take() {
                *self.waiting = Some(entry);
            }
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        self.retired.len = 0;
        if let Some(root) = self.root.take() {
            return match Arc::try_unwrap(root) {
                Ok(root) => {
                    *self.owned_root = Some(root);
                    Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 })
                }
                Err(root) => {
                    *self.root = Some(root);
                    Ok(SnapshotRetirementStep::Blocked)
                }
            };
        }
        if let Some(root) = self.owned_root.as_mut() {
            if root.len != 0 {
                root.len -= 1;
                *self.waiting = root.entries[root.len].take();
            } else {
                drop(self.owned_root.take());
            }
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        Ok(SnapshotRetirementStep::Complete)
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.root.is_none() && self.owned_root.is_none() && self.retired.len == 0 && self.waiting.is_none() && self.entry.is_none() && self.active.is_none()
    }
}

impl<P> Drop for PresencePeersRetirement<P> {
    fn drop(&mut self) {
        if !std::thread::panicking() {
            assert!(
                std::thread::panicking() || (self.root.is_none() && self.owned_root.is_none() && self.retired.len == 0 && self.waiting.is_none() && self.entry.is_none() && self.active.is_none()),
                "incomplete presence-peer retirement reached Drop without bounded disposal"
            );
        }
    }
}

#[path = "👥️presence/♻️retirement/🦀️.rs"]
mod presence_retirement;
pub use presence_retirement::PresenceStoreRetirement;

// 🚫️async: E1 impl of external `Default` — signature fixed outside this repo.
impl<P: Clone + Default, Mutation: self::Mutation<P>> Default for PresenceStore<P, Mutation> {
    fn default() -> Self {
        Self::new(P::default())
    }
}

impl<P: Clone, Mutation: self::Mutation<P>> PresenceStore<P, Mutation> {
    /// 🏗️ A roster holding only this actor's own initial presence.
    /// 🚫️async: E1 pure constructor, consumed by `Default::default()` — see R9.
    pub fn new(local: P) -> Self {
        Self {
            local: std::mem::ManuallyDrop::new(Arc::new(local)),
            peers: std::mem::ManuallyDrop::new(Arc::new(PresencePeersRoot::empty())),
            peer_retirement_factory: None,
            local_retirement_factory: None,
            local_reads: std::mem::ManuallyDrop::new(Arc::new(SnapshotReadLeaseRegistry::new())),
            active_returned_local: std::mem::ManuallyDrop::new(None),
            generation: 0,
            close_started: false,
            _mutation: PhantomData,
        }
    }

    /// 👤️ This actor's own presence — what gets broadcast.
    pub fn local(&self) -> &P {
        self.local.as_ref()
    }

    /// 🧵️ Captures the event-maintained local presence root without cloning its payload.
    pub fn local_read(&self) -> Result<SnapshotRead<P>, String>
    where
        P: Send + Sync + 'static,
    {
        if self.close_started || self.local_retirement_factory.is_none() {
            return Err("presence local read requires a live exact local retirement owner".into());
        }
        let owner = Arc::clone(&self.local);
        let lease = self.local_reads.try_issue(owner.clone()).map_err(|_| "presence local read registry is busy or exhausted".to_string())?;
        Ok(SnapshotRead::new(owner, lease))
    }

    pub fn install_local_retirement_factory(&mut self, factory: Arc<dyn SnapshotRetirementFactory<P>>) -> Result<(), String> {
        if self.close_started || self.local_retirement_factory.is_some() {
            return Err("presence local retirement factory is already installed".into());
        }
        self.local_retirement_factory = Some(factory);
        Ok(())
    }

    pub fn maintenance_local_reads_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError>
    where
        P: Send + Sync + 'static,
    {
        presence_retirement::advance_returned_local(&self.local_reads, &mut self.active_returned_local, self.local_retirement_factory.as_ref(), maximum_items, maximum_bytes)
    }

    pub fn local_read_maintenance_is_idle(&self) -> bool {
        self.active_returned_local.is_none() && !self.local_reads.has_returned()
    }

    /// ✍️ Applies local presence operations atomically, bumping `generation` after the full batch.
    pub async fn apply(&mut self, mutations: &[Mutation]) -> crate::os_spr::MutationApplyResult<()>
    where
        P: Send + Sync + 'static,
    {
        if self.close_started {
            return Err(crate::os_spr::MutationApplyError::new("mutation.apply.store-closed", "presence store no longer admits local mutations"));
        }
        if mutations.is_empty() {
            return Ok(());
        }
        let previous = self.local_read().map_err(|reason| crate::os_spr::MutationApplyError::new("mutation.apply.local-owner", reason))?;
        let mut candidate = self.local.as_ref().clone();
        for mutation in mutations {
            candidate = mutation.diff(&candidate).diff().apply(&candidate)?;
        }
        if !mutations.is_empty() {
            *self.local = Arc::new(candidate);
            self.generation = self.generation.wrapping_add(1);
        }
        previous.return_to_registry();
        Ok(())
    }

    pub fn begin_publish_one(
        &self,
        operation: semio_framework_job::OperationId,
        expected_generation: u64,
        mutation: Mutation,
        factory: Option<&dyn ArtifactEphemeralOneItemPreparationFactory<P, Mutation>>,
        root_retirement_factory: Option<Arc<dyn SnapshotRetirementFactory<P>>>,
    ) -> Result<ArtifactEphemeralOneItemPublication<P, Mutation>, ArtifactEphemeralOneItemAdmissionRejected<Mutation>>
    where
        P: Send + Sync + 'static,
    {
        let reject = |reason: String, mutation: Mutation| ArtifactEphemeralOneItemAdmissionRejected { reason, mutation };
        if self.close_started {
            return Err(reject("presence store no longer admits local publication".into(), mutation));
        }
        if self.generation != expected_generation {
            return Err(reject("presence publication generation is stale".into(), mutation));
        }
        let Some(factory) = factory else {
            return Err(reject("presence publication requires an explicit app-owned retained preparation factory".into(), mutation));
        };
        let Some(root_retirement_factory) = root_retirement_factory else {
            return Err(reject("presence publication requires an explicit local-root retirement factory".into(), mutation));
        };
        let footprint = match factory.preflight(&mutation) {
            Ok(footprint) if footprint.is_admissible() => footprint,
            Ok(_) => return Err(reject("presence publication footprint exceeds its fixed item or byte capacity".into(), mutation)),
            Err(reason) => return Err(reject(reason, mutation)),
        };
        if !self.local_retirement_factory.as_ref().is_some_and(|installed| Arc::ptr_eq(installed, &root_retirement_factory)) {
            return Err(reject("presence publication requires its exact installed local-root retirement factory".into(), mutation));
        }
        let base = match self.local_read() {
            Ok(read) => ArtifactEphemeralBaseRead(ArtifactEphemeralBaseOwner::Presence(read)),
            Err(reason) => return Err(reject(reason, mutation)),
        };
        let request = ArtifactEphemeralOneItemPreparationRequest { operation, generation: semio_framework_job::Generation(expected_generation), base, mutation };
        let preparation = match factory.begin(request) {
            Ok(preparation) => preparation,
            Err(request) => return Err(reject("presence preparation factory rejected its exact owner bundle".into(), request.mutation)),
        };
        Ok(ArtifactEphemeralOneItemPublication {
            operation,
            expected_generation,
            footprint,
            preparation: Some(preparation),
            displaced_root_retirement: None,
            root_retirement_factory: Some(root_retirement_factory),
            returned_read_registry: None,
            returned_read_retirement: None,
            owned_retirement_factory: None,
            receipt: None,
            retained_checkpoint: ArtifactStoreOneItemCheckpoint::default(),
            attempts: 0,
            published: false,
            cancel_requested: false,
            close_started: false,
            fault: None,
            phase: ArtifactStoreOneItemPublicationPhase::Preparing,
        })
    }

    pub fn advance_publish_one(&mut self, publication: &mut ArtifactEphemeralOneItemPublication<P, Mutation>, grant: ArtifactStoreOneItemGrant) -> Result<ArtifactStoreOneItemAdvance, String> {
        if publication.phase == ArtifactStoreOneItemPublicationPhase::Complete {
            return Ok(ArtifactStoreOneItemAdvance::Complete);
        }
        if publication.phase == ArtifactStoreOneItemPublicationPhase::Closing {
            return Ok(ArtifactStoreOneItemAdvance::Blocked);
        }
        if publication.phase == ArtifactStoreOneItemPublicationPhase::AwaitingAck {
            return Ok(ArtifactStoreOneItemAdvance::AwaitingAck(publication.receipt.expect("presence publication awaiting ACK retains its receipt")));
        }
        if self.close_started {
            publication.begin_close();
            return Err("presence store closed before publication".into());
        }
        if publication.cancel_requested {
            publication.begin_close();
            return Ok(ArtifactStoreOneItemAdvance::Blocked);
        }
        if self.generation != publication.expected_generation {
            publication.fault = Some("presence publication became stale before commit".into());
            publication.phase = ArtifactStoreOneItemPublicationPhase::Fault;
            publication.begin_close();
            return Err("presence publication became stale before commit".into());
        }
        if !grant.permits_one() {
            return Ok(ArtifactStoreOneItemAdvance::Blocked);
        }
        match publication.phase {
            ArtifactStoreOneItemPublicationPhase::Preparing => match publication.advance_preparation(grant)? {
                ArtifactStoreOneItemPreparationStep::Progress(checkpoint) => Ok(ArtifactStoreOneItemAdvance::Progress(checkpoint)),
                ArtifactStoreOneItemPreparationStep::Prepared(checkpoint) => {
                    publication.phase = ArtifactStoreOneItemPublicationPhase::PreparingCursor;
                    Ok(ArtifactStoreOneItemAdvance::Progress(checkpoint))
                }
                ArtifactStoreOneItemPreparationStep::Blocked => Ok(ArtifactStoreOneItemAdvance::Blocked),
            },
            ArtifactStoreOneItemPublicationPhase::PreparingCursor => {
                if publication.preparation.as_ref().and_then(|owner| owner.prepared()).is_none() {
                    return Err("presence prepared root is absent".into());
                }
                publication.phase = ArtifactStoreOneItemPublicationPhase::PreflightingCommit;
                Ok(ArtifactStoreOneItemAdvance::Progress(publication.progress()))
            }
            ArtifactStoreOneItemPublicationPhase::PreflightingCommit => {
                if self.generation == u64::MAX || publication.footprint.work_items == 0 {
                    return Err("presence publication fixed commit authority is exhausted".into());
                }
                publication.phase = ArtifactStoreOneItemPublicationPhase::Publishing;
                Ok(ArtifactStoreOneItemAdvance::Progress(publication.progress()))
            }
            ArtifactStoreOneItemPublicationPhase::Publishing => {
                let prepared = publication.preparation.as_mut().and_then(|owner| owner.take_prepared()).ok_or_else(|| "presence publication lost its prepared root".to_string())?;
                let generation_before = self.generation;
                let previous = std::mem::replace(&mut *self.local, prepared.next_root);
                let retirement_factory = publication.root_retirement_factory.as_ref().ok_or_else(|| "presence publication lost its local-root retirement factory".to_string())?;
                publication.displaced_root_retirement = Some(retirement_factory.retire(previous));
                self.generation += 1;
                let receipt = LaneItemReceipt { generation_before, generation_after: self.generation };
                publication.expected_generation = self.generation;
                publication.receipt = Some(receipt);
                publication.published = true;
                publication.phase = ArtifactStoreOneItemPublicationPhase::AwaitingAck;
                Ok(ArtifactStoreOneItemAdvance::Published(receipt))
            }
            ArtifactStoreOneItemPublicationPhase::Fault => Err(publication.fault.clone().unwrap_or_else(|| "presence publication faulted".into())),
            ArtifactStoreOneItemPublicationPhase::AwaitingAck | ArtifactStoreOneItemPublicationPhase::Closing | ArtifactStoreOneItemPublicationPhase::Complete => unreachable!("handled presence publication control phase"),
        }
    }

    pub fn cancel_publish_one(&mut self, publication: &mut ArtifactEphemeralOneItemPublication<P, Mutation>) -> bool {
        if matches!(publication.phase, ArtifactStoreOneItemPublicationPhase::Complete | ArtifactStoreOneItemPublicationPhase::Closing) {
            return false;
        }
        publication.cancel_requested = true;
        publication.begin_close();
        true
    }

    /// 🎯️ Applies one retained publication item against an exact generation and returns its
    /// per-lane receipt. A stale item is rejected before its mutation is inspected.
    pub fn apply_one(&mut self, expected_generation: u64, mutation: Mutation) -> Result<LaneItemReceipt, (String, Mutation)>
    where
        P: Send + Sync + 'static,
    {
        if self.close_started {
            return Err(("presence store no longer admits local mutations".into(), mutation));
        }
        if self.generation != expected_generation {
            return Err(("presence publication generation is stale".into(), mutation));
        }
        let before = self.generation;
        let previous = match self.local_read() {
            Ok(previous) => previous,
            Err(reason) => return Err((reason, mutation)),
        };
        let candidate = match mutation.diff(self.local.as_ref()).diff().apply(self.local.as_ref()) {
            Ok(candidate) => candidate,
            Err(error) => return Err((error.to_string(), mutation)),
        };
        *self.local = Arc::new(candidate);
        self.generation = self.generation.wrapping_add(1);
        previous.return_to_registry();
        Ok(LaneItemReceipt { generation_before: before, generation_after: self.generation })
    }

    pub fn peers_root(&self) -> Arc<PresencePeersRoot<P>> {
        Arc::clone(&self.peers)
    }

    pub fn install_peer_retirement_factory(&mut self, factory: Arc<dyn SnapshotRetirementFactory<P>>) -> Result<(), String> {
        if self.close_started || self.peer_retirement_factory.is_some() {
            return Err("presence peer retirement factory is already installed".into());
        }
        self.peer_retirement_factory = Some(factory);
        Ok(())
    }

    pub fn peer_retirement_available(&self) -> bool {
        self.peer_retirement_factory.is_some()
    }

    pub fn begin_peer_retirement(&self, retired: PresencePeersRetiredEntries<P>) -> Result<PresencePeersRetirement<P>, PresencePeersRetiredEntries<P>>
    where
        P: Send + Sync + 'static,
    {
        let Some(factory) = self.peer_retirement_factory.as_ref() else { return Err(retired) };
        Ok(PresencePeersRetirement::new(retired, factory.clone()))
    }

    pub fn begin_peer_publication(&self) -> Result<PresencePeersPublication<P>, String>
    where
        P: Send + Sync + 'static,
    {
        if self.close_started {
            return Err("presence store no longer admits peer publication".into());
        }
        let factory = self.peer_retirement_factory.as_ref().ok_or_else(|| "presence peer publication has no exact bounded snapshot retirement factory".to_string())?;
        Ok(PresencePeersPublication::new(&self.peers, factory.clone()))
    }

    pub fn publish_peer_commit(&mut self, commit: PresencePeersCommit<P>) -> Result<Option<PresencePeersRetirement<P>>, PresencePeersCommit<P>>
    where
        P: Send + Sync + 'static,
    {
        if self.close_started || !Arc::ptr_eq(&self.peers, &commit.base_root) || !self.peer_retirement_factory.as_ref().is_some_and(|factory| Arc::ptr_eq(factory, &commit.factory)) {
            return Err(commit);
        }
        let previous = std::mem::replace(&mut *self.peers, commit.root);
        let mut retirement = commit.retirement.unwrap_or_else(|| PresencePeersRetirement::new(PresencePeersRetiredEntries::empty(), commit.factory));
        *retirement.root = Some(previous);
        drop(commit.base_root);
        Ok(Some(retirement))
    }

    /// 🔢️ Bumps on every local change; never on adopting a remote peer (that needs no rebroadcast).
    pub async fn generation(&self) -> u64 {
        self.generation
    }

    /// 🪪️ Reads the event-maintained generation at an already-owned operation boundary.
    pub fn generation_now(&self) -> u64 {
        self.generation
    }
}

/// 🫧️ The TRANSIENT lane's store: ephemeral LOCAL-ONLY UI state.
///
/// 🎯️ Presence minus the roster. Nothing here is ever shared, persisted, packed, checkpointed or
/// undone — it is exactly the state that used to hide in plugin `thread_local!`s and untyped shell
/// fields, given a typed home so it can be reached only through `Emit`/`Lanes` like every other
/// lane. If a value must survive a reload it belongs in `config`; if a peer must see it, in
/// `presence`; if it is document content, in the artifact (or its draft).
pub struct TransientStore<P, Mutation> {
    current: Arc<P>,
    reads: Arc<SnapshotReadLeaseRegistry>,
    active_returned_read: Option<Box<dyn ErasedSnapshotRetirement>>,
    generation: u64,
    _mutation: PhantomData<fn() -> Mutation>,
}

// 🚫️async: E1 impl of external `Default` — signature fixed outside this repo.
impl<P: Clone + Default, Mutation: self::Mutation<P>> Default for TransientStore<P, Mutation> {
    fn default() -> Self {
        Self::new(P::default())
    }
}

impl<P: Clone, Mutation: self::Mutation<P>> TransientStore<P, Mutation> {
    /// 🚫️async: E1 pure constructor, consumed by `Default::default()` — see R9.
    pub fn new(current: P) -> Self {
        Self { current: Arc::new(current), reads: Arc::new(SnapshotReadLeaseRegistry::new()), active_returned_read: None, generation: 0, _mutation: PhantomData }
    }

    pub async fn current(&self) -> &P {
        self.current.as_ref()
    }

    /// 🧵️ Captures the event-maintained transient root without cloning its payload.
    pub fn current_root(&self) -> Arc<P> {
        self.current.clone()
    }

    /// 🧵️ Captures one tracked transient root capability for retained work.
    pub fn current_read(&self) -> Result<SnapshotRead<P>, String>
    where
        P: Send + Sync + 'static,
    {
        let owner = Arc::clone(&self.current);
        let lease = self.reads.try_issue(owner.clone()).map_err(|_| "transient read registry is busy or exhausted".to_string())?;
        Ok(SnapshotRead::new(owner, lease))
    }

    /// 🧰️ Captures the same tracked capability across a heterogeneous owner registry.
    pub fn current_read_erased(&self) -> Result<ErasedSnapshotRead, String>
    where
        P: Send + Sync + 'static,
    {
        let owner = Arc::clone(&self.current);
        let lease = self.reads.try_issue(owner.clone()).map_err(|_| "transient read registry is busy or exhausted".to_string())?;
        Ok(ErasedSnapshotRead::new(owner, lease))
    }

    /// 🧹️ Advances one returned read through its exact owned-value retirement authority.
    pub fn maintenance_returned_reads_step(&mut self, factory: &Arc<dyn ArtifactOwnedValueRetirementFactory<P>>, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError>
    where
        P: Send + Sync + 'static,
    {
        advance_returned_snapshot_read(&self.reads, &mut self.active_returned_read, factory, maximum_items, maximum_bytes)
    }

    pub fn returned_reads_terminal_is_empty(&self) -> bool {
        self.active_returned_read.is_none() && self.reads.terminal_is_empty()
    }

    pub fn current_weak(&self) -> std::sync::Weak<P> {
        Arc::downgrade(&self.current)
    }

    pub fn current_matches(&self, root: &std::sync::Weak<P>) -> bool {
        root.upgrade().is_some_and(|root| Arc::ptr_eq(&root, &self.current))
    }

    /// ✍️ Applies transient operations atomically, without history.
    pub async fn apply(&mut self, mutations: &[Mutation]) -> crate::os_spr::MutationApplyResult<()> {
        let mut candidate = self.current.as_ref().clone();
        for mutation in mutations {
            candidate = mutation.diff(&candidate).diff().apply(&candidate)?;
        }
        if !mutations.is_empty() {
            self.current = Arc::new(candidate);
            self.generation = self.generation.wrapping_add(1);
        }
        Ok(())
    }

    pub fn begin_publish_one(
        &self,
        operation: semio_framework_job::OperationId,
        expected_generation: u64,
        mutation: Mutation,
        factory: Option<&dyn ArtifactEphemeralOneItemPreparationFactory<P, Mutation>>,
        root_retirement_factory: Option<Arc<dyn SnapshotRetirementFactory<P>>>,
    ) -> Result<ArtifactEphemeralOneItemPublication<P, Mutation>, ArtifactEphemeralOneItemAdmissionRejected<Mutation>> {
        let reject = |reason: String, mutation: Mutation| ArtifactEphemeralOneItemAdmissionRejected { reason, mutation };
        if self.generation != expected_generation {
            return Err(reject("transient publication generation is stale".into(), mutation));
        }
        let Some(factory) = factory else {
            return Err(reject("transient publication requires an explicit app-owned retained preparation factory".into(), mutation));
        };
        let Some(root_retirement_factory) = root_retirement_factory else {
            return Err(reject("transient publication requires an explicit local-root retirement factory".into(), mutation));
        };
        let footprint = match factory.preflight(&mutation) {
            Ok(footprint) if footprint.is_admissible() => footprint,
            Ok(_) => return Err(reject("transient publication footprint exceeds its fixed item or byte capacity".into(), mutation)),
            Err(reason) => return Err(reject(reason, mutation)),
        };
        let request =
            ArtifactEphemeralOneItemPreparationRequest { operation, generation: semio_framework_job::Generation(expected_generation), base: ArtifactEphemeralBaseRead(ArtifactEphemeralBaseOwner::Transient(Arc::clone(&self.current))), mutation };
        let preparation = match factory.begin(request) {
            Ok(preparation) => preparation,
            Err(request) => return Err(reject("transient preparation factory rejected its exact owner bundle".into(), request.mutation)),
        };
        Ok(ArtifactEphemeralOneItemPublication {
            operation,
            expected_generation,
            footprint,
            preparation: Some(preparation),
            displaced_root_retirement: None,
            root_retirement_factory: Some(root_retirement_factory),
            returned_read_registry: None,
            returned_read_retirement: None,
            owned_retirement_factory: None,
            receipt: None,
            retained_checkpoint: ArtifactStoreOneItemCheckpoint::default(),
            attempts: 0,
            published: false,
            cancel_requested: false,
            close_started: false,
            fault: None,
            phase: ArtifactStoreOneItemPublicationPhase::Preparing,
        })
    }

    /// 📬️ Begins one transient publication from a tracked base read. Displaced roots use
    /// unique-or-release retirement so a still-live tool read cannot create a close cycle.
    pub fn begin_publish_one_leased(
        &self,
        operation: semio_framework_job::OperationId,
        expected_generation: u64,
        mutation: Mutation,
        factory: &dyn ArtifactEphemeralOneItemPreparationFactory<P, Mutation>,
        owned_retirement_factory: Arc<dyn ArtifactOwnedValueRetirementFactory<P>>,
    ) -> Result<ArtifactEphemeralOneItemPublication<P, Mutation>, ArtifactEphemeralOneItemAdmissionRejected<Mutation>>
    where
        P: Send + Sync + 'static,
    {
        let reject = |reason: String, mutation: Mutation| ArtifactEphemeralOneItemAdmissionRejected { reason, mutation };
        if self.generation != expected_generation {
            return Err(reject("transient publication generation is stale".into(), mutation));
        }
        let footprint = match factory.preflight(&mutation) {
            Ok(footprint) if footprint.is_admissible() => footprint,
            Ok(_) => return Err(reject("transient publication footprint exceeds its fixed item or byte capacity".into(), mutation)),
            Err(reason) => return Err(reject(reason, mutation)),
        };
        let base = match self.current_read() {
            Ok(read) => ArtifactEphemeralBaseRead(ArtifactEphemeralBaseOwner::TransientRead(read)),
            Err(reason) => return Err(reject(reason, mutation)),
        };
        let request = ArtifactEphemeralOneItemPreparationRequest { operation, generation: semio_framework_job::Generation(expected_generation), base, mutation };
        let preparation = match factory.begin(request) {
            Ok(preparation) => preparation,
            Err(request) => return Err(reject("transient preparation factory rejected its exact owner bundle".into(), request.mutation)),
        };
        Ok(ArtifactEphemeralOneItemPublication {
            operation,
            expected_generation,
            footprint,
            preparation: Some(preparation),
            displaced_root_retirement: None,
            root_retirement_factory: None,
            returned_read_registry: Some(self.reads.clone()),
            returned_read_retirement: None,
            owned_retirement_factory: Some(owned_retirement_factory),
            receipt: None,
            retained_checkpoint: ArtifactStoreOneItemCheckpoint::default(),
            attempts: 0,
            published: false,
            cancel_requested: false,
            close_started: false,
            fault: None,
            phase: ArtifactStoreOneItemPublicationPhase::Preparing,
        })
    }

    pub fn advance_publish_one(&mut self, publication: &mut ArtifactEphemeralOneItemPublication<P, Mutation>, grant: ArtifactStoreOneItemGrant) -> Result<ArtifactStoreOneItemAdvance, String>
    where
        P: Send + Sync + 'static,
    {
        if publication.phase == ArtifactStoreOneItemPublicationPhase::Complete {
            return Ok(ArtifactStoreOneItemAdvance::Complete);
        }
        if publication.phase == ArtifactStoreOneItemPublicationPhase::Closing {
            return Ok(ArtifactStoreOneItemAdvance::Blocked);
        }
        if publication.phase == ArtifactStoreOneItemPublicationPhase::AwaitingAck {
            return Ok(ArtifactStoreOneItemAdvance::AwaitingAck(publication.receipt.expect("transient publication awaiting ACK retains its receipt")));
        }
        if publication.cancel_requested {
            publication.begin_close();
            return Ok(ArtifactStoreOneItemAdvance::Blocked);
        }
        if self.generation != publication.expected_generation {
            publication.fault = Some("transient publication became stale before commit".into());
            publication.phase = ArtifactStoreOneItemPublicationPhase::Fault;
            publication.begin_close();
            return Err("transient publication became stale before commit".into());
        }
        if !grant.permits_one() {
            return Ok(ArtifactStoreOneItemAdvance::Blocked);
        }
        match publication.phase {
            ArtifactStoreOneItemPublicationPhase::Preparing => match publication.advance_preparation(grant)? {
                ArtifactStoreOneItemPreparationStep::Progress(checkpoint) => Ok(ArtifactStoreOneItemAdvance::Progress(checkpoint)),
                ArtifactStoreOneItemPreparationStep::Prepared(checkpoint) => {
                    publication.phase = ArtifactStoreOneItemPublicationPhase::PreparingCursor;
                    Ok(ArtifactStoreOneItemAdvance::Progress(checkpoint))
                }
                ArtifactStoreOneItemPreparationStep::Blocked => Ok(ArtifactStoreOneItemAdvance::Blocked),
            },
            ArtifactStoreOneItemPublicationPhase::PreparingCursor => {
                if publication.preparation.as_ref().and_then(|owner| owner.prepared()).is_none() {
                    return Err("transient prepared root is absent".into());
                }
                publication.phase = ArtifactStoreOneItemPublicationPhase::PreflightingCommit;
                Ok(ArtifactStoreOneItemAdvance::Progress(publication.progress()))
            }
            ArtifactStoreOneItemPublicationPhase::PreflightingCommit => {
                if self.generation == u64::MAX || publication.footprint.work_items == 0 {
                    return Err("transient publication fixed commit authority is exhausted".into());
                }
                publication.phase = ArtifactStoreOneItemPublicationPhase::Publishing;
                Ok(ArtifactStoreOneItemAdvance::Progress(publication.progress()))
            }
            ArtifactStoreOneItemPublicationPhase::Publishing => {
                let prepared = publication.preparation.as_mut().and_then(|owner| owner.take_prepared()).ok_or_else(|| "transient publication lost its prepared root".to_string())?;
                let generation_before = self.generation;
                let previous = std::mem::replace(&mut self.current, prepared.next_root);
                publication.displaced_root_retirement = Some(if let Some(factory) = publication.owned_retirement_factory.as_ref() {
                    Box::new(ReturnedSnapshotReadRetirement::new(previous, factory.clone()))
                } else {
                    publication.root_retirement_factory.as_ref().ok_or_else(|| "transient publication lost its local-root retirement factory".to_string())?.retire(previous)
                });
                self.generation += 1;
                let receipt = LaneItemReceipt { generation_before, generation_after: self.generation };
                publication.expected_generation = self.generation;
                publication.receipt = Some(receipt);
                publication.published = true;
                publication.phase = ArtifactStoreOneItemPublicationPhase::AwaitingAck;
                Ok(ArtifactStoreOneItemAdvance::Published(receipt))
            }
            ArtifactStoreOneItemPublicationPhase::Fault => Err(publication.fault.clone().unwrap_or_else(|| "transient publication faulted".into())),
            ArtifactStoreOneItemPublicationPhase::AwaitingAck | ArtifactStoreOneItemPublicationPhase::Closing | ArtifactStoreOneItemPublicationPhase::Complete => unreachable!("handled transient publication control phase"),
        }
    }

    pub fn cancel_publish_one(&mut self, publication: &mut ArtifactEphemeralOneItemPublication<P, Mutation>) -> bool {
        if matches!(publication.phase, ArtifactStoreOneItemPublicationPhase::Complete | ArtifactStoreOneItemPublicationPhase::Closing) {
            return false;
        }
        publication.cancel_requested = true;
        publication.begin_close();
        true
    }

    /// 🎯️ Applies one retained local-only item against an exact live generation.
    pub fn apply_one(&mut self, expected_generation: u64, mutation: Mutation) -> Result<LaneItemReceipt, (String, Mutation)> {
        if self.generation != expected_generation {
            return Err(("transient publication generation is stale".into(), mutation));
        }
        let before = self.generation;
        let candidate = match mutation.diff(self.current.as_ref()).diff().apply(self.current.as_ref()) {
            Ok(candidate) => candidate,
            Err(error) => return Err((error.to_string(), mutation)),
        };
        self.current = Arc::new(candidate);
        self.generation = self.generation.wrapping_add(1);
        Ok(LaneItemReceipt { generation_before: before, generation_after: self.generation })
    }

    /// 🔄️ Discards everything — what a host does when a view closes.
    pub async fn reset(&mut self, current: P) {
        self.current = Arc::new(current);
        self.generation = self.generation.wrapping_add(1);
    }

    /// 🔢️ Bumps on every change, so a renderer can skip untouched frames.
    pub async fn generation(&self) -> u64 {
        self.generation
    }

    /// 🪪️ Reads the event-maintained transient generation without suspension.
    pub fn generation_now(&self) -> u64 {
        self.generation
    }

    /// ♻️ Detaches this store's exact root/read registry and installs a fresh terminal root.
    pub fn begin_retirement(&mut self, terminal: P, factory: Arc<dyn ArtifactOwnedValueRetirementFactory<P>>) -> TransientStoreRetirement<P>
    where
        P: Send + Sync + 'static,
    {
        let next_generation = self.generation.wrapping_add(1);
        let displaced = std::mem::replace(self, Self::new(terminal));
        self.generation = next_generation;
        TransientStoreRetirement::new(displaced, factory)
    }
}

/// ♻️ Detached transient root plus every returned/live tracked read.
pub struct TransientStoreRetirement<P> {
    root: std::mem::ManuallyDrop<Option<Arc<P>>>,
    reads: std::mem::ManuallyDrop<Option<Arc<SnapshotReadLeaseRegistry>>>,
    active_returned: std::mem::ManuallyDrop<Option<Box<dyn ErasedSnapshotRetirement>>>,
    active_root: std::mem::ManuallyDrop<Option<Box<dyn ErasedSnapshotRetirement>>>,
    factory: Option<Arc<dyn ArtifactOwnedValueRetirementFactory<P>>>,
}

impl<P> TransientStoreRetirement<P> {
    fn new<Mutation>(store: TransientStore<P, Mutation>, factory: Arc<dyn ArtifactOwnedValueRetirementFactory<P>>) -> Self {
        let store = std::mem::ManuallyDrop::new(store);
        Self {
            root: std::mem::ManuallyDrop::new(Some(unsafe { std::ptr::read(&store.current) })),
            reads: std::mem::ManuallyDrop::new(Some(unsafe { std::ptr::read(&store.reads) })),
            active_returned: std::mem::ManuallyDrop::new(unsafe { std::ptr::read(&store.active_returned_read) }),
            active_root: std::mem::ManuallyDrop::new(None),
            factory: Some(factory),
        }
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.root.is_none() && self.reads.is_none() && self.active_returned.is_none() && self.active_root.is_none() && self.factory.is_none()
    }
}

impl<P: Send + Sync + 'static> TransientStoreRetirement<P> {
    pub fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError> {
        if maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if let Some(reads) = self.reads.as_ref() {
            if self.active_returned.is_some() || reads.has_returned() {
                return advance_returned_snapshot_read(
                    reads,
                    &mut self.active_returned,
                    self.factory.as_ref().ok_or_else(|| semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "transient retirement lost its owned factory"))?,
                    1,
                    maximum_bytes,
                );
            }
        }
        if let Some(active) = self.active_root.as_mut() {
            return match active.close_step(1, maximum_bytes)? {
                SnapshotRetirementStep::Complete if active.terminal_is_empty() => {
                    drop(self.active_root.take());
                    Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 })
                }
                SnapshotRetirementStep::Complete => Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "transient root completed without its exact empty witness")),
                SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items > 1 || released_bytes > maximum_bytes => {
                    Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "transient root exceeded its exact grant"))
                }
                step => Ok(step),
            };
        }
        if let Some(root) = self.root.take() {
            *self.active_root = Some(Box::new(ReturnedSnapshotReadRetirement::new(
                root,
                self.factory.as_ref().ok_or_else(|| semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "transient retirement lost its owned factory"))?.clone(),
            )));
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if self.reads.as_ref().is_some_and(|reads| !reads.terminal_is_empty()) {
            return Ok(SnapshotRetirementStep::Blocked);
        }
        if self.reads.take().is_some() {
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if self.factory.take().is_some() {
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        Ok(SnapshotRetirementStep::Complete)
    }
}

impl<P> Drop for TransientStoreRetirement<P> {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.terminal_is_empty()), "transient store retirement reached Drop before terminal-empty ownership");
        unsafe {
            std::mem::ManuallyDrop::drop(&mut self.root);
            std::mem::ManuallyDrop::drop(&mut self.reads);
            std::mem::ManuallyDrop::drop(&mut self.active_returned);
            std::mem::ManuallyDrop::drop(&mut self.active_root);
        }
    }
}

//#region 🔖️InteractionStore
/// 🕹️ Ephemeral LOCAL-ONLY lane for the framework interaction mechanism's hover half — the
/// `PresenceStore`/`TransientStore` sibling for `InteractionState.hover`.
///
/// 🎯️ Only hover lives here. Selection + `active_mode`/`active_granularity` are
/// **persisted-local** (`InteractionState`'s other three fields) and already flow through the
/// ordinary `ConfigStore` (`ArtifactStore<Config, ConfigMutation>`) via `ArtifactCommand::
/// ApplyInLane { lane: HistoryLane::Interaction, .. }` — no new store type needed for that half,
/// it is the ENTIRE point of the `HistoryLane` mechanism above. Hover must never take that path
/// (never persisted, never in `Edit`/`Change` history), so it gets this dedicated ephemeral
/// sibling instead, shaped exactly like `TransientStore` (single local value, no peer roster —
/// peers' hover arrives over the wire as `PresencePeer.interaction`, not through this store).
///
/// `S`/`Mutation` are supplied by the caller (mirrors `PresenceStore<A::Presence,
/// A::PresenceMutation>` in `VcsArtifactApp`): this crate has no dependency edge to the
/// `semio-framework` crate that owns `InteractionState`/`DomainHover` (that crate depends on
/// THIS one, for its `spr`/`dsl`/`pack` types — the reverse edge would cycle), so `S` stays
/// generic here and gets instantiated with the app's concrete hover-shaped type one layer up,
/// where that dependency edge actually exists.
#[derive(Clone, Debug)]
pub struct InteractionStore<S, Mutation> {
    hover: S,
    generation: u64,
    _mutation: PhantomData<fn() -> Mutation>,
}

// 🚫️async: E1 impl of external `Default` — signature fixed outside this repo.
impl<S: Clone + Default, Mutation: self::Mutation<S>> Default for InteractionStore<S, Mutation> {
    fn default() -> Self {
        Self::new(S::default())
    }
}

impl<S: Clone, Mutation: self::Mutation<S>> InteractionStore<S, Mutation> {
    /// 🏗️ Starts with this actor's own initial hover state (typically empty).
    /// 🚫️async: E1 pure constructor, consumed by `Default::default()` — see R9.
    pub fn new(hover: S) -> Self {
        Self { hover, generation: 0, _mutation: PhantomData }
    }

    /// 👁️ This actor's own hover — what the presence heartbeat mirrors onto `PresenceDomain.hovered`.
    pub async fn hover(&self) -> &S {
        &self.hover
    }

    /// ✍️ Applies hover updates atomically. The caller's `Mutation` impl is expected to route
    /// through the framework's `next_hover` pure fn before landing here.
    pub async fn apply(&mut self, mutations: &[Mutation]) -> crate::os_spr::MutationApplyResult<()> {
        let mut candidate = self.hover.clone();
        for mutation in mutations {
            candidate = mutation.diff(&candidate).diff().apply(&candidate)?;
        }
        if !mutations.is_empty() {
            self.hover = candidate;
            self.generation = self.generation.wrapping_add(1);
        }
        Ok(())
    }

    /// 🔄️ Discards hover — a host clears this when a view/window closes (nothing left to hover).
    pub async fn reset(&mut self, hover: S) {
        self.hover = hover;
        self.generation = self.generation.wrapping_add(1);
    }

    /// 🔢️ Bumps on every local hover change; drives the same broadcast-coalescing signal as
    /// `PresenceStore::generation`.
    pub async fn generation(&self) -> u64 {
        self.generation
    }
}
