    pub fn decode_document_controlled(bytes: &[u8], spec: &RecordSpec, options: &PackDecodeOptions, control: &mut crate::os_dsl::NativeDecodeControl<'_>) -> Result<(RecordValue, crate::os_pack::DecodeReport), PackError> {
